<?php
require_once __DIR__ . '/_layout.php';requirePermission('reservations.manage');$agencyIds=currentAgencyIds();if(!$agencyIds)$agencyIds=[0];$agencyId=(int)($_GET['agency_id']??$agencyIds[0]);requireAgencyAccess($agencyId);
[$page,$size,$offset]=paginationParameters();$q=trim((string)($_GET['q']??''));$status=validateChoice($_GET['status']??'',reservationStatuses(),'');$source=validateChoice($_GET['source']??'',reservationSources(),'');$customerId=max(0,(int)($_GET['customer_id']??0));$vehicleId=max(0,(int)($_GET['vehicle_id']??0));$from=validDateValue($_GET['date_from']??'');$to=validDateValue($_GET['date_to']??'');
$where=['r.agency_id=:agency','r.archived_at IS NULL'];$params=['agency'=>$agencyId];if($q!==''){$where[]='(r.reference LIKE :q1 OR c.first_name LIKE :q2 OR c.last_name LIKE :q3 OR v.registration_number LIKE :q4)';foreach(range(1,4)as$i)$params['q'.$i]='%'.$q.'%';}if($status!==''){$where[]='r.status=:status';$params['status']=$status;}if($source!==''){$where[]='r.source=:source';$params['source']=$source;}if($customerId){$where[]='r.customer_id=:customer';$params['customer']=$customerId;}if($vehicleId){$where[]='r.vehicle_id=:vehicle';$params['vehicle']=$vehicleId;}if($from){$where[]='r.return_at>=:from';$params['from']=$from->format('Y-m-d').' 00:00:00';}if($to){$where[]='r.pickup_at<:to';$params['to']=$to->modify('+1 day')->format('Y-m-d').' 00:00:00';}$whereSql=implode(' AND ',$where);
$count=(int)dbFetchOne("SELECT COUNT(*) n FROM reservations r JOIN customers c ON c.id=r.customer_id LEFT JOIN vehicles v ON v.id=r.vehicle_id WHERE $whereSql",$params)['n'];$rows=dbFetchAll("SELECT r.*,c.first_name,c.last_name,v.registration_number,v.brand,v.model,vc.name category_name FROM reservations r JOIN customers c ON c.id=r.customer_id LEFT JOIN vehicles v ON v.id=r.vehicle_id LEFT JOIN vehicle_categories vc ON vc.id=r.category_id WHERE $whereSql ORDER BY r.pickup_at DESC,r.id DESC LIMIT $size OFFSET $offset",$params);$hasNext=$offset+count($rows)<$count;
$agencies=dbFetchAll("SELECT id,name FROM agencies WHERE archived_at IS NULL AND status='active' ORDER BY name");$customers=dbFetchAll("SELECT id,first_name,last_name FROM customers WHERE agency_id=:agency AND archived_at IS NULL ORDER BY last_name,first_name",['agency'=>$agencyId]);$vehicles=dbFetchAll("SELECT id,registration_number,brand,model FROM vehicles WHERE agency_id=:agency AND archived_at IS NULL ORDER BY registration_number",['agency'=>$agencyId]);
backofficeHeader(t('page.reservations.title'),'reservations.php');pageHeader('page.reservations.title','page.reservations.description',['breadcrumbs'=>[['label'=>'nav.rentals'],['label'=>'nav.reservations']],'primary'=>['label'=>'action.create_reservation','href'=>'reservation_form.php?agency_id='.$agencyId],'secondary'=>['label'=>'nav.planning','href'=>'reservation_planning.php?agency_id='.$agencyId]]);?>
<form class="filters" method="get"><label><?=e(t('common.search'))?><input name="q" value="<?=e($q)?>" placeholder="<?=e(t('placeholder.reservation_search'))?>"></label><label><?=e(t('field.agency'))?><select name="agency_id"><?php foreach($agencies as$a):if(currentUserRole()!==ROLE_OWNER&&!in_array((int)$a['id'],$agencyIds,true))continue;?><option value="<?=e($a['id'])?>" <?=$agencyId===(int)$a['id']?'selected':''?>><?=e($a['name'])?></option><?php endforeach;?></select></label><label><?=e(t('common.status'))?><select name="status"><option value=""><?=e(t('common.all'))?></option><?php foreach(reservationStatuses()as$v):?><option value="<?=$v?>" <?=$status===$v?'selected':''?>><?=e(translatedStatus($v))?></option><?php endforeach;?></select></label><label><?=e(t('field.source'))?><select name="source"><option value=""><?=e(t('common.all'))?></option><?php foreach(reservationSources()as$v):?><option value="<?=e($v)?>" <?=$source===$v?'selected':''?>><?=e(t('option.'.strtolower($v)))?></option><?php endforeach;?></select></label><label><?=e(t('field.customer'))?><select name="customer_id"><option value=""><?=e(t('common.all'))?></option><?php foreach($customers as$c):?><option value="<?=e($c['id'])?>" <?=$customerId===(int)$c['id']?'selected':''?>><?=e($c['last_name'].' '.$c['first_name'])?></option><?php endforeach;?></select></label><label><?=e(t('field.vehicle'))?><select name="vehicle_id"><option value=""><?=e(t('common.all'))?></option><?php foreach($vehicles as$v):?><option value="<?=e($v['id'])?>" <?=$vehicleId===(int)$v['id']?'selected':''?>><?=e($v['registration_number'].' — '.$v['brand'].' '.$v['model'])?></option><?php endforeach;?></select></label><label><?=e(t('field.date_from'))?><input type="date" name="date_from" value="<?=e($_GET['date_from']??'')?>"></label><label><?=e(t('field.date_to'))?><input type="date" name="date_to" value="<?=e($_GET['date_to']??'')?>"></label><button class="btn secondary"><?=e(t('common.filter'))?></button><a class="btn ghost" href="reservations.php?agency_id=<?=e($agencyId)?>"><?=e(t('common.reset'))?></a></form>
<section class="card"><div class="section-heading"><div class="section-card-header"><h2><?=navigationIcon('rentals')?><?=e(t('section.reservation_register'))?></h2></div><span><?=e(t('message.record_count',['count'=>$count]))?></span></div><div class="table-wrap"><table><thead><tr><th><?=e(t('field.reference'))?></th><th><?=e(t('field.customer'))?></th><th><?=e(t('field.vehicle'))?></th><th><?=e(t('field.period'))?></th><th><?=e(t('field.source'))?></th><th><?=e(t('field.total'))?></th><th><?=e(t('field.balance'))?></th><th><?=e(t('common.status'))?></th><th><?=e(t('common.actions'))?></th></tr></thead><tbody><?php foreach($rows as$r):?><tr><td><a href="reservation_detail.php?id=<?=e($r['id'])?>"><?=isolatedValue($r['reference'],'reference-value')?></a></td><td><?=e($r['first_name'].' '.$r['last_name'])?></td><td><?=isolatedValue($r['registration_number'],'registration-value')?><br><small><?=e($r['category_name'])?></small></td><td><?=formattedDateTime($r['pickup_at'])?><br><?=formattedDateTime($r['return_at'])?></td><td><span class="badge"><?=e(t('option.'.strtolower($r['source'])))?></span></td><td><?=money($r['total_amount'],$r['currency'])?></td><td><?=money($r['remaining_amount'],$r['currency'])?></td><td><?=statusBadge($r['status'])?></td><td><?=actionMenu([['label'=>'common.view','href'=>'reservation_detail.php?id='.$r['id']],['label'=>'common.edit','href'=>'reservation_edit.php?id='.$r['id']]])?></td></tr><?php endforeach;?></tbody></table><?php if(!$rows)echo emptyState('empty.no_filtered_records','empty.adjust_filters');?></div><?=pagination($page,$hasNext,'reservations.php',['agency_id'=>$agencyId,'q'=>$q,'status'=>$status,'source'=>$source,'customer_id'=>$customerId,'vehicle_id'=>$vehicleId,'date_from'=>$_GET['date_from']??'','date_to'=>$_GET['date_to']??'','size'=>$size])?></section><?php backofficeFooter();
